require "rails_helper"

RSpec.describe ReviewSchedule do
  before { seed_judge }
  let(:user) { create_user }
  let(:problem) { Problem.first }

  it "returns only reviews that are due" do
    # Check the SQL query generated by our due scope
    sql = ReviewSchedule.due.to_sql
    expect(sql).to include("next_review_date")
    expect(sql).to include("<=")
  end

  # Test all five performance ratings
  {
    1 => 1,   # Very difficult: reset to 1 day
    2 => 2,   # Difficult: reset to 2 days
    3 => 4,   # Moderate: keep the 4-day interval
    4 => 8,   # Easy: double to 8 days
    5 => 12   # Very easy: triple to 12 days
  }.each do |rating, expected_interval|
    it "calculates the correct interval for rating #{rating}" do
      # Start with a 4-day review interval
      schedule = ReviewSchedule.new(
        interval_days: 4,
        next_review_date: Date.current
      )

      allow(schedule).to receive(:save!).and_return(true)
      schedule.update_from_rating!(rating: rating)
      expect(schedule.interval_days).to eq(expected_interval)
      expect(schedule.next_review_date).to eq(
                                             Date.current + expected_interval.days
                                           )
    end
  end

  it "rejects invalid performance ratings" do
    schedule = ReviewSchedule.new(interval_days: 4)

    # Ratings outside 1–5 should raise an error
    expect {
      schedule.update_from_rating!(rating: 6)
    }.to raise_error(ArgumentError)
  end
end
